    }
  ],
  "dataModel": {
    "value": {
      "antiAddiction": {
        "title": "防沉迷",
        "status": "已超时",
        "alertText": "危险告警",
        "screen": {
          "remainingPercent": 47,
          "remainingPercentText": "47%",
          "todayUsed": "4小时20分",
          "limit": "3小时30分",
          "overTime": "50分钟"
        },
        "weather": {
          "location": "室外",
          "condition": "阴",
          "temperature": "29℃"
        },
        "dnd": {
          "enabled": false,
          "actionText": "开启勿扰"
        }
      }
    }
  },
  "assetCandidates": []
}

